def trigger_emotional_intervention(
    user_id,
    real_time_metrics,   # {"typing_speed": ..., "voice_pitch": ..., "sentiment_score": ...}
    historical_data      # preferences, accessibility needs, learning patterns, consent settings
):
    """
    Returns a recommended intervention and rationale.
    This function must not diagnose emotional states or optimize for dependency.
    """

    # 1. Load privacy and support preferences
    prefs = historical_data.get("support_preferences", {})
    if not prefs.get("emotional_checkins_enabled", False):
        return {
            "action": "no_action",
            "reason": "User has not enabled proactive check-ins."
        }

    # Respect quiet hours, age-specific policies, and notification limits
    if is_quiet_hours(user_id) or exceeded_daily_prompt_limit(user_id):
        return {
            "action": "no_action",
            "reason": "Respecting notification limits or quiet hours."
        }

    # 2. Validate and normalize data
    metrics = sanitize_metrics(real_time_metrics)

    # Do not use voice pitch as a standalone emotional classifier.
    # Missing or noisy signals should lower confidence, not trigger intervention.
    signal_quality = assess_signal_quality(metrics)
    if signal_quality < 0.5:
        return {
            "action": "no_action",
            "reason": "Insufficiently reliable real-time signals."
        }

    # 3. Check for explicit safety language only
    # This should be based on clear text/content, not inferred mood.
    if contains_explicit_immediate_safety_concern(metrics):
        return {
            "action": "safety_support",
            "message": (
                "I’m concerned by what you said. Are you in immediate danger? "
                "If so, contact local emergency services or a trusted person now."
            ),
            "options": [
                "show_local_crisis_resources",
                "contact_trusted_person",
                "continue_when_ready"
            ],
            "human_review": True
        }

    # 4. Compare current learning behavior with the student's own baseline.
    # Avoid making population-level assumptions about mood or ability.
    baseline = historical_data.get("learning_baseline", {})
    changes = compare_with_personal_baseline(metrics, baseline)

    # 5. Select the least intrusive useful intervention.
    # Signals are treated as uncertainty, not proof of an emotional state.
    if changes.get("sustained_struggle", False):
        return {
            "action": "offer_scaffold",
            "message": (
                "This topic seems to be taking extra effort. "
                "Would you like a simpler explanation, an example, or a short break?"
            ),
            "options": [
                "simpler_explanation",
                "worked_example",
                "practice_easier_problem",
                "take_break",
                "dismiss"
            ],
            "rationale": "Observed learning difficulty relative to the user's baseline."
        }

    if changes.get("rapid_pacing_or_rushing", False):
        return {
            "action": "offer_pacing_support",
            "message": (
                "Would you like to slow down and review the key idea before continuing?"
            ),
            "options": [
                "review_key_idea",
                "continue",
                "dismiss"
            ],
            "rationale": "Current pace may reduce retention; no emotional state inferred."
        }

    if changes.get("possible_frustration", False):
        return {
            "action": "brief_check_in",
            "message": (
                "How would you like to proceed?"
            ),
            "options": [
                "try_hint",
                "see_another_explanation",
                "switch_activity",
                "take_break",
                "dismiss"
            ],
            "rationale": (
                "Multiple weak signals suggest the current activity may be difficult; "
                "the student chooses the response."
            )
        }

    # 6. Reinforce autonomy and learning—not engagement for its own sake.
    if is_good_time_for_reflection(user_id, historical_data):
        return {
            "action": "optional_reflection",
            "message": (
                "Before moving on, would you like to explain the idea in your own words?"
            ),
            "options": [
                "reflect",
                "continue",
                "dismiss"
            ],
            "rationale": "Retrieval and explanation can improve retention."
        }

    return {
        "action": "no_action",
        "reason": "No sufficiently reliable need for intervention."
    }
