def offer_focus_support(user_id, activity_data, tutor_state, preferences, consent):
    """
    Provide optional study support without surveillance, blocking, or lock-in.

    activity_data should contain only tutor-owned interaction events, e.g.:
      - repeated_hint_requests
      - long_pause_seconds
      - repeated_incorrect_attempts
      - user_clicked_external_help_button  # explicit, in-app action

    Do not collect:
      - clipboard contents
      - browser history or URLs
      - keystrokes outside the tutor
      - app-switch counts from other applications
    """

    if not consent.focus_support_enabled:
        return {"action": "none"}

    if preferences.get("pause_interventions", False):
        return {"action": "none"}

    # Do not infer intent from app switching or browser activity.
    # Only respond to observable learning friction inside the tutor.
    friction = (
        activity_data.get("repeated_incorrect_attempts", 0) >= 2
        or activity_data.get("long_pause_seconds", 0) >= 90
        or activity_data.get("repeated_hint_requests", 0) >= 2
    )

    if not friction:
        return {"action": "continue"}

    # Offer choices rather than automatically interrupting.
    options = [
        "try_scaffolding_hint",
        "see_worked_example",
        "review_prerequisite",
        "take_short_break",
        "continue_independently"
    ]

    if activity_data.get("user_clicked_external_help_button", False):
        options += [
            "open_teacher_approved_resource",
            "compare_with_external_explanation"
        ]

    return {
        "action": "offer_learning_support",
        "message": (
            "Would support be useful, or would you prefer to keep working "
            "independently?"
        ),
        "choices": options,
        "non_blocking": True,
        "dismissible": True,
        "explanation": (
            "This suggestion is based on recent activity in the lesson, "
            "not on monitoring other apps or private content."
        )
    }


def handle_support_choice(choice, problem_context, tutor_state):
